#include <iostream>
#include <string>
#include <utility>
#include <vector>
using namespace std;

struct P {
    string name;
    int age;
    static int ctor, copy, move;
    P(string n, int a) : name(std::move(n)), age(a) { ++ctor; }
    P(const P& o) : name(o.name), age(o.age) { ++copy; }
    P(P&& o) noexcept : name(std::move(o.name)), age(o.age) { ++move; }
};
int P::ctor = 0;
int P::copy = 0;
int P::move = 0;

int main() {
    {
        vector<P> v; v.reserve(8);
        P::ctor = P::copy = P::move = 0;
        v.push_back(P("A", 1));          // 先造临时对象，再移入容器
        cout << "push_back(P(\"A\",1))   ctor=" << P::ctor
             << " copy=" << P::copy << " move=" << P::move << "\n";
    }
    {
        vector<P> v; v.reserve(8);
        P::ctor = P::copy = P::move = 0;
        v.emplace_back("A", 1);          // 直接把参数转发到容器内存里构造
        cout << "emplace_back(\"A\",1)   ctor=" << P::ctor
             << " copy=" << P::copy << " move=" << P::move << "\n";
    }
    {
        vector<P> v; v.reserve(8);
        P p("A", 1);                     // 构造发生在计时之前
        P::ctor = P::copy = P::move = 0;
        v.push_back(p);                  // 传入已存在的左值 → 只能拷贝
        cout << "push_back(已存在对象)  ctor=" << P::ctor
             << " copy=" << P::copy << " move=" << P::move << "\n";
    }
    cout << "\n结论：emplace_back 省掉一次临时对象构造；\n";
    cout << "      但若你手上已有对象，emplace_back(p) 反而和 push_back 一样要拷贝\n";
}
